import java.io.*;
import java.util.*;

public class Cutlet {
    private static final FastScanner fs = new FastScanner(System.in);
    private static final PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    public static void main(String[] args) {
        solve();
        out.flush();
    }

    private static void solve() {
        int n = fs.nextInt();
        int k = fs.nextInt();

        int[] l = new int[k];
        int[] r = new int[k];
        for (int i = 0; i < k; i++) {
            l[i] = fs.nextInt();
            r[i] = fs.nextInt();
        }

        List<Interval>[] dp = new List[2 * k + 1];
        for (int i = 0; i < dp.length; i++) {
            dp[i] = new ArrayList<>();
        }
        dp[0].add(new Interval(0, 0));

        int prev = 0;
        for (int i = 0; i < k; i++) {
            List<Interval>[] next = new List[dp.length];
            for (int ii = 0; ii < dp.length; ii++) {
                next[ii] = new ArrayList<>();
            }

            int delta = l[i] - prev;
            for (int index = 0; index < dp.length; index++) {
                if (index % 2 == 0) {
                    for (Interval interval : dp[index]) {
                        interval.l += delta;
                        interval.r += delta;
                    }
                }
            }

            delta = r[i] - l[i];
            for (int ii = 0; ii < dp.length; ii++) {
                if (ii % 2 == 0) {
                    for (Interval interval : dp[ii]) {
                        next[ii].add(new Interval(interval.l + delta, interval.r + delta));
                        next[ii + 1].add(new Interval(interval.l, interval.r + delta));
                        next[ii + 2].add(new Interval(interval.l, interval.r + delta));
                    }
                } else {
                    for (Interval interval : dp[ii]) {
                        next[ii].add(new Interval(interval.l, interval.r));
                        next[ii + 1].add(new Interval(interval.l, interval.r + delta));
                        next[ii + 2].add(new Interval(interval.l, interval.r + delta));
                    }
                }
            }

            prev = r[i];
            for (int index = 0; index < dp.length; index++) {
                dp[index].clear();

                List<Interval> list = next[index];
                list.sort(Comparator.naturalOrder()); // Interval implements Comparable

                Interval pr = null;
                for (Interval interval : list) {
                    if (interval.l > n) break;
                    if (pr != null && pr.r >= interval.l) {
                        pr.r = Math.max(pr.r, interval.r);
                    } else {
                        if (pr != null && !find(dp, pr, index)) {
                            dp[index].add(pr);
                        }
                        pr = interval;
                    }
                }
                if (pr != null && !find(dp, pr, index)) {
                    dp[index].add(pr);
                }
            }
        }

        int delta = 2 * n - prev;
        for (int index = 0; index < dp.length; index++) {
            if (index % 2 == 0) {
                for (Interval interval : dp[index]) {
                    interval.l += delta;
                    interval.r += delta;
                }
            }
        }

        for (int i = 0; i < dp.length; i++) {
            for (Interval interval : dp[i]) {
                if (interval.l <= n && interval.r >= n) {
                    out.println("Full");
                    out.println(i);
                    return;
                }
            }
        }

        out.println("Hungry");
    }

    private static boolean find(List<Interval>[] dp, Interval value, int index) {
        for (int i = index - 2; i >= 0; i--) {
            List<Interval> list = dp[i];
            int ind = Collections.binarySearch(list, value);
            if (ind < 0) {
                ind = -ind - 2; // insertion point - 1
                if (ind >= 0 && list.get(ind).r >= value.r) {
                    return true;
                }
            } else {
                if (list.get(ind).r >= value.r) {
                    return true;
                }
            }
        }
        return false;
    }

    static class Interval implements Comparable<Interval> {
        int l, r;

        Interval(int l, int r) {
            this.l = l;
            this.r = r;
        }

        @Override
        public int compareTo(Interval o) {
            return Integer.compare(this.l, o.l);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024 * 10];
        private int ptr = 0;
        private int len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() {
            try {
                int c;
                int res = 0;
                do {
                    c = read();
                    if (c == -1) return res;
                } while (c < '0' || c > '9');
                res = c - '0';
                while (true) {
                    c = read();
                    if (c < '0' || c > '9') return res;
                    res *= 10;
                    res += c - '0';
                }
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

